  "headline": "FDA's records trace our supply to a plant classified OAI 150 days before the posting",
  "headline_cites": ["D11"],
  "sentences": [
    {
      "text": "FDA first posted the fentanyl citrate injection shortage on 2012-01-01 and it remains current as of 2026-10-21.",
      "cites": ["E29", "E26", "E28"]
    },
    {
      "text": "Hospira, Inc. (FEI 1021343) is a registered plant on our product labels for NDC 00409909422.",
      "cites": ["E17", "E1", "E5"]
    },
    {
      "text": "FDA inspection 740633 at that plant ended 2011-08-04 and was classified OAI, 150 days before the shortage posting.",
      "cites": ["E11", "D11"]
    },
    {
      "text": "FDA inspection 732886 at the same plant ended 2011-06-17 and was classified OAI, 198 days before the posting.",
      "cites": ["E10", "D10"]
    },
    {
      "text": "FDA inspection 639034 at the plant ended 2010-01-19 and was classified OAI, 712 days before the posting.",
      "cites": ["E9", "D6"]
    },
    {
      "text": "A Warning Letter was issued to the plant on 2010-04-12, 629 days before the posting.",
      "cites": ["E16", "D7"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. (FEI 2220525) is also a registered plant on our labels and has only VAI inspections in FDA's record.",
      "cites": ["E25", "E18", "E19", "E20", "E21", "E22", "E23", "E24"]
    }
  ]
}
